#!/bin/bash
# Live check of host-setup.sh's sysvinit pieces on a host without systemd, run
# as root from the repository: sudo deploy/agentc/sysvinit-check.sh
#
# Run it after host-setup.sh, whether or not the owner has opted in to the real
# loop. It never installs, enables, starts, stops or reads the real loop: it
# does not touch /etc/init.d/agentc-run, its rc links, /run/agentc-run.pid or
# /var/log/agentc-run.log. A fake supervisor stands in for agentc-supervisor,
# and the fake loop's init script (generated by host-setup.sh's own
# run_sysv_script under the name agentc-run-check), pidfile and log live in a
# temporary directory. Only two system paths are created and removed again:
# /etc/init.d/agentc-run-check for insserv's dry run (no rc links) and
# /etc/cron.d/agentc-sysvinit-check. Both must be absent beforehand (a
# leftover of an interrupted check); nothing else is ever deleted. Checks:
#   1. insserv accepts the LSB script's boot order (after agentc-firewall and
#      agentc-egress) in a dry run;
#   2. start runs the wrapper, a crash restarts the loop after 30 s, status works;
#   3. stop passes SIGTERM for the drain, then kills what is left in the group;
#   4. cron runs agentc-cron from /etc/cron.d with an environment file.
set -euo pipefail

HERE=$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")
NAME=agentc-run-check
INITD_DIR=/etc/init.d
CRON_DIR=/etc/cron.d
T=
FAILED=0

# Sets the check's paths. T is its temporary directory; the fake loop's
# pidfile and log are inside it, never the real loop's.
set_paths() {
  PIDFILE=$T/run.pid
  LOG=$T/run.log
  INITD_CHECK=$INITD_DIR/$NAME
  CRON_CHECK=$CRON_DIR/agentc-sysvinit-check
}

# Prints PASS or FAIL for check $1, decided by running the rest as a command.
check() {
  local what=$1; shift
  if "$@"; then echo "PASS $what"; else echo "FAIL $what"; FAILED=1; fi
}

# True when systemd is the running init.
has_systemd() { [ -d /run/systemd/system ]; }

# Exits unless this is root on a host without systemd, and neither of the two
# system paths the check creates is left over from an interrupted run. The
# real agentc-run (installed, opted in or running) is none of its business.
preflight() {
  [ "$(id -u)" = 0 ] || { echo "run as root (sudo $0)" >&2; exit 2; }
  ! has_systemd || { echo "this host runs systemd; the check is for sysvinit hosts" >&2; exit 2; }
  for path in "$INITD_CHECK" "$CRON_CHECK"; do
    [ ! -e "$path" ] || { echo "$path exists: left over from an interrupted check? remove it and run the check again" >&2; exit 2; }
  done
  for tool in start-stop-daemon insserv cron; do
    command -v "$tool" >/dev/null || { echo "needs $tool" >&2; exit 2; }
  done
}

# Stops the fake loop and removes every file the check created.
cleanup() {
  [ ! -x "$T/$NAME" ] || "$T/$NAME" stop >/dev/null 2>&1 || true
  rm -f -- "$INITD_CHECK" "$CRON_CHECK"
  [ -z "$T" ] || rm -rf -- "$T"
}

# The fake `agentc-supervisor run`: records each run, crashes (exit 3) once
# when $T/crash exists, otherwise starts a TERM-ignoring "launch" in its
# process group and drains for 2 s on SIGTERM.
fake_supervisor() {
  cat <<EOF
#!/bin/sh
echo \$\$ >> $T/runs
if [ -f $T/crash ]; then rm -f $T/crash; exit 3; fi
sh -c 'trap "" TERM; echo \$\$ > $T/launch; exec sleep 600' &
trap 'sleep 2; echo drained >> $T/drained; exit 0' TERM
while :; do sleep 0.2; done
EOF
}

# Builds the init script with host-setup.sh's own generator, pointed at the
# fake supervisor, the wrapper copied into $T, and the fake loop's own name,
# pidfile and log. host-setup.sh is sourced in a subshell, so its functions
# (its own main among them) never replace ours.
build_fixture() {
  mkdir -p "$T/bin"
  install -m 0755 "$HERE/agentc-run-sysv.sh" "$T/agentc-run-sysv"
  fake_supervisor > "$T/bin/agentc-supervisor"; chmod 0755 "$T/bin/agentc-supervisor"
  # shellcheck source=host-setup.sh
  (source "$HERE/host-setup.sh"; PREFIX=$T; RUN_WRAPPER=$T/agentc-run-sysv; run_sysv_script "$NAME" "$PIDFILE" "$LOG") > "$T/$NAME"
  chmod 0755 "$T/$NAME"
}

# Succeeds once command $2... succeeds, polling for up to $1 seconds.
within() {
  local seconds=$1; shift
  for _ in $(seq $((seconds * 5))); do "$@" && return 0; sleep 0.2; done
  return 1
}

# Succeeds once the fake loop has started at least $1 times.
runs() { [ "$(wc -l < "$T/runs" 2>/dev/null || echo 0)" -ge "$1" ]; }
# Succeeds while the pid recorded in file $1 is alive; dead is the reverse.
alive() { kill -0 "$(cat "$1")" 2>/dev/null; }
dead() { ! alive "$1"; }

# insserv dry run: the script's Required-Start/Stop resolve against the real
# agentc-firewall and agentc-egress scripts on this host. insserv needs the
# script in /etc/init.d, so the fake loop's, which has its own name, goes there
# for the dry run only.
check_boot_order() {
  install -m 0755 "$T/$NAME" "$INITD_CHECK"
  check "insserv accepts the boot order (dry run)" insserv -n "$INITD_CHECK"
  rm -f -- "$INITD_CHECK"
}

# start, crash restart and status.
check_start_and_restart() {
  touch "$T/crash"
  "$T/$NAME" start
  check "start writes the pidfile and the wrapper runs" within 5 alive "$PIDFILE"
  check "status reports running" "$T/$NAME" status
  echo "waiting about 30 s for the crash restart..."
  check "a crash restarts the loop after the delay" within 45 runs 2
  check "the restart is logged" grep -q "exited 3; restarting in 30s" "$LOG"
  check "the restarted loop started a launch" within 5 test -s "$T/launch"
}

# stop: drain, then the group kill takes the TERM-ignoring launch.
check_stop() {
  "$T/$NAME" stop
  check "stop let the loop drain" grep -qs drained "$T/drained"
  check "stop killed the leftover launch in the group" within 5 dead "$T/launch"
  check "stop removed the pidfile" test ! -e "$PIDFILE"
  check "status reports stopped" bash -c "! '$T/$NAME' status"
}

# cron runs agentc-cron from /etc/cron.d with an environment file.
check_cron() {
  install -m 0755 "$HERE/agentc-cron.sh" "$T/agentc-cron"
  printf 'CHECK_VALUE="from env file"\n' > "$T/check.env"
  # Single quotes keep cron's own shell from expanding $CHECK_VALUE: only
  # the job's shell, after agentc-cron loaded check.env, may.
  printf 'AGENTC_CRON_LOG_DIR=%s\n* * * * * root %s --name check --env %s -- /bin/sh -c %s\n' \
    "$T" "$T/agentc-cron" "$T/check.env" "'echo value=\$CHECK_VALUE'" > "$CRON_CHECK"
  echo "waiting up to 70 s for cron..."
  check "cron ran agentc-cron with the environment file" within 70 grep -qs "value=from env file" "$T/agentc-check.log"
  rm -f -- "$CRON_CHECK"
}

# Runs every check and exits 1, printing the logs, if any failed.
main() {
  preflight
  T=$(mktemp -d /tmp/agentc-sysvinit-check.XXXXXX)
  trap cleanup EXIT
  set_paths
  build_fixture
  check_boot_order
  check_start_and_restart
  check_stop
  check_cron
  if [ "$FAILED" = 0 ]; then echo "sysvinit check: all PASS"; return 0; fi
  echo "--- $LOG"; cat "$LOG" 2>/dev/null || true
  echo "--- $T/agentc-check.log"; cat "$T/agentc-check.log" 2>/dev/null || true
  echo "sysvinit check: FAILURES above"; exit 1
}

# Sourcing the file (the test does) defines the functions without running them.
if [ "${BASH_SOURCE[0]}" = "$0" ]; then main "$@"; fi
